db.exec(`PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,name TEXT,title TEXT,role TEXT,avatar_seed TEXT,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS processes(id INTEGER PRIMARY KEY,code TEXT UNIQUE,title TEXT,type TEXT,owner_user_id INTEGER,purpose TEXT,scope TEXT,resources TEXT,source_text TEXT,inputs TEXT,activities TEXT,outputs TEXT,destinations TEXT,rev_no TEXT,rev_date TEXT,FOREIGN KEY(owner_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS kpis(id INTEGER PRIMARY KEY,process_id INTEGER,title TEXT,formula TEXT,unit TEXT,acceptance REAL,acceptance_text TEXT,direction TEXT,frequency TEXT,start_month INTEGER,data_owner TEXT,data_source TEXT,critical INTEGER DEFAULT 0,due_day INTEGER DEFAULT 25,FOREIGN KEY(process_id) REFERENCES processes(id));
CREATE TABLE IF NOT EXISTS monitoring_results(id INTEGER PRIMARY KEY,kpi_id INTEGER,year INTEGER,month INTEGER,value REAL,note TEXT,source_ref TEXT,data_verified INTEGER DEFAULT 0,created_at TEXT,created_by INTEGER,due_at TEXT,on_time INTEGER,FOREIGN KEY(kpi_id) REFERENCES kpis(id));
CREATE TABLE IF NOT EXISTS analyses(id INTEGER PRIMARY KEY,kpi_id INTEGER,year INTEGER,month INTEGER,trend TEXT,factors TEXT,conclusion TEXT,decision TEXT,reason TEXT,created_at TEXT,created_by INTEGER);
CREATE TABLE IF NOT EXISTS capas(id INTEGER PRIMARY KEY,code TEXT UNIQUE,process_id INTEGER,kpi_id INTEGER,analysis_id INTEGER,subject TEXT,problem TEXT,root_cause TEXT,status TEXT,opened_at TEXT,closed_at TEXT,owner_user_id INTEGER,FOREIGN KEY(process_id) REFERENCES processes(id));
CREATE TABLE IF NOT EXISTS actions(id INTEGER PRIMARY KEY,capa_id INTEGER,title TEXT,responsible_user_id INTEGER,due_at TEXT,status TEXT,completed_at TEXT,effectiveness_due_at TEXT,FOREIGN KEY(capa_id) REFERENCES capas(id));
CREATE TABLE IF NOT EXISTS effectiveness(id INTEGER PRIMARY KEY,action_id INTEGER,result TEXT,evidence TEXT,evaluated_by INTEGER,evaluated_at TEXT,FOREIGN KEY(action_id) REFERENCES actions(id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER,title TEXT,message TEXT,href TEXT,kind TEXT,created_at TEXT,read_at TEXT);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY,user_id INTEGER,entity TEXT,entity_id TEXT,action TEXT,before_json TEXT,after_json TEXT,reason TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY,code TEXT UNIQUE,title TEXT,rev_no TEXT,rev_date TEXT,purpose TEXT,scope TEXT,definitions TEXT,responsibilities TEXT,related_docs TEXT,flow_summary TEXT);
`);

const MONTHS=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
const sessions=new Map();
function now(){return new Date().toISOString();}
function j(v){try{return JSON.stringify(v)}catch{return '{}'}}
function esc(s){return String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));}
function list(s){try{return JSON.parse(s||'[]')}catch{return []}}
function one(sql,...p){return db.prepare(sql).get(...p)}
function all(sql,...p){return db.prepare(sql).all(...p)}
function run(sql,...p){return db.prepare(sql).run(...p)}
function avatar(name){const a=String(name||'کاربر').trim().split(/\s+/); const ini=(a[0]?.[0]||'ک')+(a[1]?.[0]||''); return `<span class="avatar">${esc(ini)}</span>`;}
function cookie(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').map(x=>x.trim()).filter(Boolean).map(x=>{let i=x.indexOf('=');return [x.slice(0,i),x.slice(i+1)]}));}
function currentUser(req){const sid=cookie(req).sid; const id=sessions.get(sid); return id?one('SELECT * FROM users WHERE id=?',id):null;}
function body(req){return new Promise((resolve,reject)=>{let d='';req.on('data',c=>{d+=c;if(d.length>1e6)req.destroy()});req.on('end',()=>resolve(Object.fromEntries(new URLSearchParams(d))));req.on('error',reject)});}
function redirect(res,to){res.writeHead(302,{Location:to});res.end();}
function response(res,html,status=200,type='text/html; charset=utf-8'){res.writeHead(status,{'Content-Type':type,'Cache-Control':'no-store'});res.end(html)}
function audit(user,entity,id,action,before,after,reason=''){run('INSERT INTO audit_log(user_id,entity,entity_id,action,before_json,after_json,reason,created_at) VALUES(?,?,?,?,?,?,?,?)',user?.id||null,entity,String(id||''),action,j(before),j(after),reason,now());}

function deadlineFor(year,month,day=25){
  const starts=[[2026,2,21],[2026,3,21],[2026,4,22],[2026,5,22],[2026,6,23],[2026,7,23],[2026,8,23],[2026,9,23],[2026,10,22],[2026,11,22],[2027,0,21],[2027,1,20]];
  if(year!==1405) return new Date(Date.UTC(2026,starts[month-1][1],starts[month-1][2]+Math.min(day,28))).toISOString();
  const [gy,gm,gd]=starts[month-1]; return new Date(Date.UTC(gy,gm,gd+Math.min(day,28)-1,20,29,59)).toISOString();
}
function dueMonth(kpi,m){const f=kpi.frequency; const s=Number(kpi.start_month||1); if(f==='ماهانه')return true; if(f==='فصلی'||f==='سه‌ماهه')return ((m-s)%3+3)%3===0; if(f==='شش‌ماهه')return ((m-s)%6+6)%6===0; if(f==='سالانه')return m===s; return true;}
function resultState(kpi,r,m){if(!dueMonth(kpi,m))return ['not-due','هنوز موعد ندارد']; if(!r){const due=new Date(deadlineFor(1405,m,kpi.due_day)); return new Date()>due?['missing','سررسیدشده و ثبت‌نشده']:['pending','در انتظار موعد'];} if(kpi.acceptance==null)return ['monitor','پایشی']; const ok=kpi.direction==='کاهشی'?r.value<=kpi.acceptance:r.value>=kpi.acceptance; return ok?['good','قابل قبول']:['bad','نیازمند اقدام'];}
function spark(vals,limit){const pts=vals.map((v,i)=>v==null?null:[i,v]).filter(Boolean); if(!pts.length)return '<span class="muted">داده کافی نیست</span>'; const ys=pts.map(x=>x[1]).concat(limit==null?[]:[limit]); const min=Math.min(...ys),max=Math.max(...ys); const y=v=>36-((v-min)/(max-min||1))*28; const x=i=>8+i*(104/11); const poly=pts.map(p=>`${x(p[0])},${y(p[1])}`).join(' '); return `<svg class="spark" viewBox="0 0 120 44" aria-label="نمودار روند">${limit==null?'':`<line x1="6" x2="114" y1="${y(limit)}" y2="${y(limit)}" class="limit"/>`}<polyline points="${poly}"/><circle cx="${x(pts.at(-1)[0])}" cy="${y(pts.at(-1)[1])}" r="3"/></svg>`;}

